@pytest.mark.parametrize("version", VERSIONS)
@pytest.mark.parametrize("op,args,kind,path", CASES, ids=[row[0] for row in CASES])
def test_op_emits_lab_path(version, op, args, kind, path):
    builder = WebProxyBatchBuilder(version)
    getattr(builder, op)(*args)
    assert builder.get_operations() == [{"op": kind, "path": path}]


def test_every_builder_op_has_a_row():
    builder = WebProxyBatchBuilder("1.5")
    ops = {
        name
        for name, _ in inspect.getmembers(builder, predicate=inspect.ismethod)
        if name.startswith(("set_", "delete_", "add_")) and name not in INTERNAL_BUILDER_METHODS
    }
    assert ops == {row[0] for row in CASES}
